css:
body {
    font-family: Arial, sans-serif;
    margin: 20px;
    font-size: 10px;
    position: relative;
    min-height: 100vh;
    padding-bottom: 120px;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 20px;
    page-break-inside: auto;
}

th, td {
    padding: 8px;
    text-align: left;
    border: 1px solid black;
    font-size: 12px;
}

tbody::after {
    display: block;
    height: 20px;
}

.header-table {
    border-collapse: collapse;
    width: 100%;
}

.header-table td {
    border: none;
    padding: 5px;
}

.title_1 {
    font-size: 15px;
    border: none;
    color: black;
}

.title {
    font-size: 10px;
    font-weight: bold;
    border: none;
    color: black;
}

.border_square {
    border: 1px solid black !important;
    padding: 5px !important;
    margin: 0 !important;
}
.signature {
    width: 25% !important;
    height: auto;
}

.print-format img.signature {
    max-width: 30%;
}

.print-format img.logo {
    max-width: 75%;
}

.spacer-row td {
    height: 20px;
    border: none;
    padding: 0;
}
.print-format td, .print-format th {
  padding: 4px !important;
}

.print-format th {
  color: black;
  font-weight: 600;
  border-bottom-width: 1px !important;
}
.terms-wrapper {
    border: 1px solid black;
    padding: 0px -1px;
    font-size: 10px;
}

.terms-title {
    text-align: center;
    font-weight: bold;
    margin-bottom: 10px;
    color: black;
}

tfoot {
    display: table-footer-group !important;
    position: fixed !important;
    bottom: 0;
    left: 0;
    width: 100%;
    background: white;
    text-align: -webkit-center;
    height: auto;
    z-index: 1000;
}

tfoot tr td {
    padding: 5px 10px;
    font-size: 10px;
    color: black;
    background: white;
}
